// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

/**
* Interface describing `dlasv2`.
*/
interface Routine {
	/**
	* Computes the singular value decomposition of a 2x2 upper triangular matrix.
	*
	* ## Notes
	*
	* -   `abs(SSMAX)` is the larger singular value.
	* -   `abs(SSMIN)` is the smaller singular value.
	* -   (`CSL`,`SNL`) and (`CSR`,`SNR`) are the left and right singular vectors for `abs(SSMAX)`.
	*
	* @param F - the (0,0) element of matrix
	* @param G - the (0,1) element of matrix
	* @param H - the (1,1) element of matrix
	* @param out - output array containing `SSMIN`, `SSMAX`, `SNR`, `CSR`, `SNL`, and `CSL` respectively
	* @returns output array
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var out = new Float64Array( 6 );
	*
	* dlasv2( 2.0, 3.0, 4.0, out );
	* // out => <Float64Array>[ ~1.5513, ~5.1569, ~0.9665, ~0.2567, ~0.7497, ~0.6618 ]
	*/
	( F: number, G: number, H: number, out: Float64Array ): Float64Array;

	/**
	* Computes the singular value decomposition of a 2x2 upper triangular matrix using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   `abs(SSMAX)` is the larger singular value.
	* -   `abs(SSMIN)` is the smaller singular value.
	* -   (`CSL`,`SNL`) and (`CSR`,`SNR`) are the left and right singular vectors for `abs(SSMAX)`.
	*
	* @param F - the (0,0) element of matrix
	* @param G - the (0,1) element of matrix
	* @param H - the (1,1) element of matrix
	* @param out - output array containing `SSMIN`, `SSMAX`, `SNR`, `CSR`, `SNL`, and `CSL` respectively
	* @param strideOut - stride length for `out`
	* @param offsetOut - starting index of `out`
	* @returns output array
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var out = new Float64Array( 6 );
	*
	* dlasv2.ndarray( 2.0, 3.0, 4.0, out, 1, 0 );
	* // out => <Float64Array>[ ~1.5513, ~5.1569, ~0.9665, ~0.2567, ~0.7497, ~0.6618 ]
	*/
	ndarray( F: number, G: number, H: number, out: Float64Array, strideOut: number, offsetOut: number ): Float64Array;
}

/**
* Computes the singular value decomposition of a 2x2 upper triangular matrix.
*
* ## Notes
*
* -   `abs(SSMAX)` is the larger singular value.
* -   `abs(SSMIN)` is the smaller singular value.
* -   (`CSL`,`SNL`) and (`CSR`,`SNR`) are the left and right singular vectors for `abs(SSMAX)`.
*
* @param F - the (0,0) element of matrix
* @param G - the (0,1) element of matrix
* @param H - the (1,1) element of matrix
* @param out - output array containing `SSMIN`, `SSMAX`, `SNR`, `CSR`, `SNL`, and `CSL` respectively
* @returns output array
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var out = new Float64Array( 6 );
*
* dlasv2( 2.0, 3.0, 4.0, out );
* // out => <Float64Array>[ ~1.5513, ~5.1569, ~0.9665, ~0.2567, ~0.7497, ~0.6618 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var out = new Float64Array( 6 );
*
* dlasv2.ndarray( 2.0, 3.0, 4.0, out, 1, 0 );
* // out => <Float64Array>[ ~1.5513, ~5.1569, ~0.9665, ~0.2567, ~0.7497, ~0.6618 ]
*/
declare var dlasv2: Routine;


// EXPORTS //

export = dlasv2;
